def build(subj, rows, title):
    qs = []
    for i, (tp, q, code, opts, c, ex) in enumerate(rows):
        cs = list(c)
        assert all(x in L[:len(opts)] for x in cs) and len(set(o.lower() for o in opts)) == len(opts), (subj, i)
        ans = '; '.join('%s) %s' % (x, opts[L.index(x)]) for x in cs)
        item = {'id': 'v94-%s-%d' % (subj, i + 1), 'n': i + 1, 'topic': tp, 'multi': subj == 'db', 'correct': cs, 'q': q,
                'opts': [{'l': L[j], 't': t} for j, t in enumerate(opts)], 'hard': True,
                'ex': 'Дұрыс жауап%s — %s. Шешімі: %s' % ('тар' if len(cs) > 1 else '', ans, ex)}
        if code: item['code'] = code
        qs.append(item)
    key = 'v94-%s' % subj
    d = {'key': key, 'variant': 94, 'subject': subj, 'lang': 'kz', 'origLang': 'kz', 'source': 'ai', 'title': title, 'questions': qs}
    open(os.path.join(ROOT, 'data/sets/%s.js' % key), 'w', encoding='utf-8').write('Shyn.addSet(' + json.dumps(d, ensure_ascii=False) + ');\n')
    return key

keys = [build('fundamentals', FU, 'Нұсқа 94 · Қиын есептер: ТГО математикасы'),
        build('algo', ALGO, 'Нұсқа 94 · Қиын есептер: алгоритмдер (C деңгейі)'),
        build('db', DB, 'Нұсқа 94 · Қиын есептер: деректер қоры (C деңгейі)')]
idx = os.path.join(ROOT, 'data/index.js'); s = open(idx, encoding='utf-8').read()
arr = json.loads(s[s.index('['):s.rindex(']') + 1]); arr = [a for a in arr if not a.startswith('v94-')] + keys
open(idx, 'w', encoding='utf-8').write('Shyn.setFiles(' + json.dumps(arr, ensure_ascii=False) + ');\n')
print('v94', len(FU), len(ALGO), len(DB))
